"""Naskah sumber materi PGMI. Semua isi ditulis untuk penjelasan konseptual."""
TOPICS=[]
def add(slug,title,group,opening,goals,sections,cases,activity,checks,reflection,source):
 TOPICS.append(dict(slug=slug,title=title,group=group,opening=opening,goals=goals,sections=sections,cases=cases,activity=activity,checks=checks,reflection=reflection,source=source))
PHYS=('OpenStax. College Physics 2e.','https://openstax.org/details/books/college-physics-2e')
BIO=('OpenStax. Biology 2e.','https://openstax.org/details/books/biology-2e')
add('hakikat','Hakikat IPA dan Cara Kerja Sains','Fondasi IPA',
'Bagian luar gelas berisi es menjadi basah. Apakah air merembes dari dalam, atau berasal dari tempat lain?',
['Membedakan pengamatan dan penjelasan.','Menyusun pertanyaan yang dapat diselidiki dengan bukti.'],[
('Apa yang kita pelajari dalam IPA?','Apakah mengetahui jawaban saja sudah cukup?', 'IPA menghasilkan pengetahuan tentang alam melalui pengamatan, penyelidikan, dan penalaran. Pengetahuan berupa fakta, konsep, model, hukum, dan teori saling berkaitan. Hukum menggambarkan keteraturan; teori menyediakan penjelasan yang luas. Teori ilmiah tidak otomatis berubah menjadi hukum setelah lama digunakan. Cara memperoleh pengetahuan dan sikap terhadap bukti merupakan bagian dari IPA yang perlu dipelajari calon guru.'),
('Pengamatan berbeda dari penjelasan','Apakah “gelas bocor” merupakan hasil melihat langsung?', '“Ada titik air pada sisi luar gelas” adalah pengamatan. “Air itu merembes” merupakan penjelasan yang masih perlu diuji. Pengamatan dapat menggunakan indra dan alat. Penjelasan menghubungkan pengamatan dengan pengetahuan yang dimiliki. Dua orang dapat mengamati gejala serupa tetapi menawarkan penjelasan berbeda; bukti membantu menilai penjelasan tersebut.'),
('Dari pertanyaan ke penyelidikan','Bagaimana membandingkan dua penjelasan dengan adil?', 'Pertanyaan ilmiah perlu memungkinkan pencarian bukti. Untuk menguji asal air di luar gelas, gunakan wadah utuh yang kering, bandingkan air dingin dengan air suhu ruang, dan amati bagian luarnya. Upayakan kondisi lain serupa. Tentukan apa yang diubah, apa yang diamati, dan apa yang dijaga sama. Pengulangan membantu memeriksa konsistensi, tetapi satu demonstrasi tidak menjawab semua kemungkinan.'),
('Bersedia memperbaiki pendapat','Jika hasil tidak sesuai dugaan, apakah penyelidikan gagal?', 'Hasil yang berbeda dapat mengungkap kekeliruan dugaan atau masalah prosedur. Periksa keduanya sebelum menyimpulkan. Catat data apa adanya dan komunikasikan caranya. Kegiatan ilmiah dapat kembali ke pertanyaan awal; tidak semua penyelidikan berupa eksperimen dengan urutan identik. Mengamati, mengelompokkan, mengukur, memprediksi, menginferensi, dan mengomunikasikan merupakan keterampilan proses sains.')],
[['amati','Amati','Apa yang terlihat pada luar gelas?', 'Permukaan luar gelas dingin menjadi bertitik air. Pernyataan ini mencatat gejala, belum menetapkan asal air.'],['duga','Ajukan dugaan','Apakah titik air pasti menandakan kebocoran?', 'Belum. Uap air di udara dapat mengembun pada permukaan yang cukup dingin. Keutuhan wadah dan kondisi pembanding perlu diperiksa.'],['uji','Bandingkan','Mengapa perlu gelas pembanding?', 'Gelas suhu ruang yang serupa membantu memeriksa peran kondisi dingin. Perbandingan yang dirancang lebih kuat daripada sekadar menyetujui dugaan.']],
['Cermati gambar gelas pada eksplorasi. Tulis satu pengamatan dan dua kemungkinan penjelasan.','Rancang perbandingan dua gelas tanpa harus melakukannya di kelas. Sebutkan apa yang diubah dan apa yang diamati.'],
[['Lantai basah berarti pasti baru hujan. Setujukah Anda?','Tidak. Lantai dapat basah karena dibersihkan atau tumpahan. Kondisi basah teramati; asal air perlu bukti tambahan.'],['Jika dugaan tidak didukung hasil, bolehkah hasil diubah?','Tidak. Periksa pengamatan dan prosedur, lalu revisi penjelasan bila diperlukan.']],
'Bagaimana menanggapi jawaban awal siswa yang berbeda dari penjelasan ilmiah?',BIO)
add('pengukuran','Besaran Satuan dan Pengukuran','Fisika',
'Dua orang mengukur meja yang sama dengan jengkal. Mengapa hasilnya dapat berbeda?',
['Menjelaskan perlunya satuan baku dan alat yang tepat.','Mengenali sumber perbedaan hasil pengukuran.'],[
('Apa yang sebenarnya diukur?','Apakah “meja ini panjang” sudah merupakan hasil pengukuran?', 'Pengukuran membandingkan suatu besaran dengan satuan yang disepakati. Panjang, waktu, massa, suhu, dan volume merupakan contoh besaran. Hasil perlu menyebut nilai dan satuan, misalnya panjang buku 20 cm. Angka tanpa satuan tidak memberi informasi lengkap.'),
('Mengapa membutuhkan satuan baku?','Apakah jengkal setiap orang sama?', 'Satuan tidak baku seperti jengkal berguna untuk mengenalkan perbandingan, tetapi ukurannya berbeda antarorang. Satuan baku memudahkan komunikasi. Pilih alat sesuai besaran dan ukuran objek: mistar untuk panjang buku, stopwatch untuk selang waktu, neraca untuk massa, dan termometer untuk suhu. Jangka membuat konstruksi lingkaran; busur derajat mengukur sudut.'),
('Bagaimana membaca alat dengan benar?','Apakah ujung mistar selalu sama dengan tanda nol?', 'Mulai dari tanda nol skala, bukan otomatis tepi plastik. Letakkan alat sejajar panjang yang diukur dan pandang skala dari posisi yang tepat. Untuk pengukuran waktu manual, reaksi saat menekan tombol dapat memengaruhi hasil. Pengukuran ulang membantu memeriksa konsistensi, tetapi tidak menghapus semua kesalahan alat atau cara.'),
('Apakah alat memberi hasil yang mutlak tepat?','Mengapa dua hasil yang sedikit berbeda belum tentu berarti salah satu orang ceroboh?', 'Alat memiliki keterbatasan skala dan kondisi penggunaan. Laporkan hasil sesuai kemampuan alat; jangan menambahkan angka yang tidak teramati. Pada PGMI, utamakan pemilihan alat, prosedur membaca, satuan, dan penjelasan alasan perbedaan. Pembacaan volume cairan dan suhu dapat dibahas melalui gambar ketika alat tidak tersedia.')],
[['nol','Mulai di nol','Di mana awal buku harus diletakkan?', 'Sejajarkan ujung buku dengan tanda nol. Tepi mistar dapat menyisakan jarak sebelum skala pertama.'],['geser','Nol tidak digunakan','Jika pengukuran dimulai pada tanda 2 cm, bagaimana membaca panjang?', 'Gunakan selisih bacaan akhir dan awal. Contoh pada gambar: mulai 2 cm dan berakhir 8 cm berarti panjangnya 6 cm.'],['ulang','Pengukuran ulang','Mengapa mencatat hasil pengulangan?', 'Pengulangan memperlihatkan konsistensi. Perbedaan kecil dapat berasal dari penempatan alat atau pembacaan, sehingga cara kerja juga perlu dicatat.']],
['Ukur panjang buku yang sama dua kali dengan mistar. Catat hasil dan satuannya.','Bandingkan dengan teman. Periksa posisi nol, kesejajaran, dan cara melihat skala sebelum membahas perbedaan.'],
[['Apakah jangka dan busur derajat mempunyai fungsi sama?','Tidak. Jangka membuat konstruksi, sedangkan busur derajat mengukur besar sudut.'],['Apakah hasil pengukuran berulang harus selalu berbeda?','Tidak. Hasil dapat sama atau berbeda dalam batas skala alat dan prosedur yang digunakan.']],
'Instruksi singkat apa yang paling membantu siswa membaca mistar dengan benar?',PHYS)
add('zat','Materi Zat dan Perubahannya','Fisika',
'Es mencair, gula larut, dan kertas terbakar. Apakah ketiganya mengalami perubahan yang sama?',
['Membedakan wujud zat melalui sifat dan model partikel.','Menjelaskan perubahan fisika dan kimia dengan bukti yang relevan.'],[
('Apakah udara termasuk materi?','Jika tidak terlihat, apakah berarti tidak ada?', 'Materi mempunyai massa dan menempati ruang. Udara dapat mengisi balon walaupun tidak tampak. Benda merupakan objek; bahan penyusunnya dapat berbeda. Sendok logam dan sendok kayu mempunyai fungsi serupa tetapi sifat bahan berbeda, sehingga pemanfaatannya juga dapat berbeda.'),
('Mengapa wujud zat berbeda?','Apakah partikel dalam es benar-benar diam?', 'Padatan memiliki bentuk dan volume relatif tetap. Cairan mengikuti bentuk wadah dengan volume relatif tetap. Gas memenuhi ruang yang tersedia. Dalam model partikel, partikel padat berdekatan dan bergetar, cair berdekatan tetapi dapat bergeser, sedangkan gas berjauhan dan bergerak bebas. Model titik bukan gambar bentuk asli atau ukuran partikel. Padatan tidak selalu memiliki susunan partikel teratur.'),
('Apa yang berubah ketika es mencair?','Apakah es yang menjadi air menghasilkan bahan kimia baru?', 'Perubahan padat menjadi cair disebut mencair; kebalikannya membeku. Cair menjadi gas disebut menguap, dan gas menjadi cair disebut mengembun. Padat dapat menyublim langsung menjadi gas; kebalikannya deposisi. Air tetap air ketika berubah wujud. Penguapan terjadi juga tanpa mendidih. Uap air sebagai gas tidak tampak; kabut putih yang terlihat berisi tetes air kecil.'),
('Berubah bentuk atau terbentuk zat baru?','Apakah muncul gelembung selalu berarti perubahan kimia?', 'Perubahan fisika tidak mengubah identitas kimia zat, misalnya memotong kertas atau mencairkan es. Pembakaran dan perkaratan menghasilkan zat berbeda. Warna, gelembung, dan bau merupakan petunjuk yang perlu ditafsirkan; air mendidih bergelembung tanpa reaksi kimia. Dapat kembali seperti semula bukan satu-satunya pembeda. Pada pembakaran, gas yang lepas juga termasuk hasil perubahan.'),
('Ke mana garam yang larut pergi?','Dapatkah garam terlarut ditahan saringan biasa?', 'Air garam merupakan campuran homogen; pasir dalam air merupakan campuran heterogen. Garam masih ada meskipun tidak tampak sebagai kristal. Saringan biasa memisahkan pasir, tetapi tidak memisahkan garam terlarut. Penguapan dapat meninggalkan garam; penampungan uap yang dikondensasikan digunakan jika airnya juga ingin diperoleh.')],
[['padat','Padat','Bagaimana jarak dan gerak partikel?', 'Partikel berdekatan dan bergetar di sekitar posisinya. Bentuk benda relatif tetap; partikel tidak harus diam atau selalu tersusun teratur.'],['cair','Cair','Apa yang memungkinkan cairan mengalir?', 'Partikel masih berdekatan tetapi dapat bergeser. Identitas partikel tidak berubah hanya karena zat mencair.'],['gas','Gas','Apakah titik partikel menjadi lebih besar?', 'Tidak. Model memperlihatkan jarak yang lebih renggang. Partikel zat tidak ikut membesar seperti balon.']],
['Kelompokkan es mencair, kertas dipotong, besi berkarat, dan kertas terbakar. Berikan alasan berdasarkan identitas zat.','Buat rencana memisahkan pasir dan air. Jelaskan mengapa cara yang sama tidak memisahkan garam terlarut.'],
[['Pakaian kering karena airnya musnah. Benarkah?','Air berpindah ke udara sebagai uap melalui penguapan.'],['Semua perubahan kimia dapat dipastikan dari warna. Benarkah?','Tidak. Perubahan warna harus ditafsirkan bersama kondisi dan bukti lain.']],
'Gambar seperti apa yang dapat membuat anak keliru mengira partikel ikut mencair?',PHYS)
add('gaya','Gaya dan Gerak','Fisika',
'Buku berhenti setelah didorong di atas meja. Apakah gerak selalu membutuhkan dorongan terus-menerus?',
['Menjelaskan hubungan gaya dengan perubahan gerak dan bentuk.','Membedakan posisi, jarak, waktu, dan kecepatan secara sederhana.'],[
('Kapan sebuah benda disebut bergerak?','Penumpang yang duduk di bus bergerak atau diam?', 'Jawabannya bergantung pada acuan. Penumpang diam terhadap kursi tetapi bergerak terhadap jalan saat bus melaju. Gerak berarti perubahan posisi terhadap acuan. Jarak menggambarkan panjang lintasan yang ditempuh. Perpindahan memperhatikan perubahan dari posisi awal ke akhir, sehingga berjalan mengelilingi lapangan dapat menempuh jarak walaupun kembali ke titik semula.'),
('Apa yang dilakukan gaya?','Apakah gaya selalu membuat benda bergerak?', 'Gaya merupakan tarikan atau dorongan akibat interaksi. Gaya dapat mengubah kecepatan, arah gerak, atau bentuk. Spons yang diremas berubah bentuk. Buku yang diam tetap mengalami tarikan gravitasi dan dorongan penopang meja. Beberapa gaya dapat saling menyeimbangkan; adanya gaya tidak selalu menyebabkan perubahan gerak.'),
('Mengapa benda melambat?','Apakah buku menyimpan dorongan lalu kehabisan?', 'Sesudah tangan dilepas, dorongan tangan tidak lagi bekerja. Gesekan dengan meja memperlambat buku. Pada model tanpa hambatan dengan gaya-gaya seimbang, benda yang sudah bergerak dapat mempertahankan gerak lurus berkecepatan tetap; ini pokok Hukum I Newton. Hukum II Newton menghubungkan gaya keseluruhan dengan perubahan gerak dan peran massa secara kualitatif. Jika gaya keseluruhan tidak seimbang, geraknya berubah. Hukum III Newton membahas pasangan gaya yang sama besar dan berlawanan arah pada benda berbeda: tangan mendorong buku, buku juga mendorong tangan.'),
('Bagaimana membandingkan gerak?','Jika jarak sama, siapa yang lebih cepat?', 'Untuk lintasan sama, waktu lebih singkat berarti kelajuan rata-rata lebih besar. Perhitungan sederhana boleh menggunakan jarak dibagi waktu. Contoh: menempuh 10 meter selama 5 sekon berarti kelajuan rata-rata 2 meter per sekon. Ini berbeda dari kecepatan sesaat. Dalam fisika, kecepatan juga memuat arah; berbelok mengubah kecepatan meskipun kelajuannya tetap.'),
('Gaya apa yang dekat dengan kita?','Apakah gesekan selalu merugikan?', 'Gravitasi menjelaskan kecenderungan benda jatuh ke arah Bumi. Gesekan membantu berjalan tanpa selip dan menghambat buku yang meluncur. Pegas yang diregangkan dapat menarik kembali. Benda bermassa lebih besar lebih sulit diubah geraknya oleh gaya keseluruhan yang sama; pembahasan ini cukup dibandingkan secara kualitatif.')],
[['seimbang','Gaya seimbang','Apakah benda yang bergerak pasti melambat?', 'Jika gaya keseluruhan seimbang, model ideal mempertahankan gerak lurus berkecepatan tetap. Benda juga dapat tetap diam bila awalnya diam.'],['dorong','Dorongan lebih besar','Apa yang berubah jika gaya keseluruhan tidak seimbang?', 'Gerak dapat bertambah cepat, melambat, atau berubah arah bergantung arah gaya dan keadaan gerak awal.'],['gesek','Setelah dilepas','Mengapa buku di meja akhirnya berhenti?', 'Gesekan memberikan pengaruh berlawanan terhadap gerak meluncur. Benda bukan kehabisan gaya yang tersimpan.']],
['Geser buku perlahan pada meja. Amati geraknya setelah tangan dilepas dan jelaskan interaksi yang masih bekerja.','Gunakan kalkulator jarak–waktu di bawah untuk membandingkan dua perjalanan dengan jarak sama. Jelaskan hasilnya dalam kalimat.'],
[['Buku diam berarti tidak ada gaya. Setujukah Anda?','Tidak. Gravitasi dan gaya penopang dapat saling menyeimbangkan.'],['Gesekan sebaiknya dihilangkan di semua tempat. Setujukah Anda?','Tidak. Berjalan dan mengerem membutuhkan interaksi gesekan.']],
'Bagaimana menjelaskan mengapa bola berhenti tanpa mengatakan “gayanya habis”?',PHYS)
add('energi','Usaha Energi dan Perubahannya','Fisika',
'Menahan tas membuat lelah, tetapi tas tidak berpindah. Apakah ada usaha pada tas?',
['Membedakan usaha pada benda dari rasa lelah.','Menelusuri perubahan energi pada alat dan kegiatan sehari-hari.'],[
('Apa arti usaha dalam fisika?','Apakah mendorong dinding diam sama dengan menggeser meja?', 'Usaha dalam fisika berkaitan dengan gaya dan perpindahan. Ketika gaya dorong menggeser meja searah dorongan, gaya itu melakukan usaha pada meja. Pada dinding yang tetap diam, tidak ada usaha mekanik oleh dorongan pada dinding dalam model ini. Tubuh tetap memakai energi. Kita perlu membedakan proses pada dinding dan proses di tubuh.'),
('Dari mana perubahan mendapat energi?','Apakah energi hanya ada pada benda yang bergerak?', 'Energi gerak terlihat perannya pada bola menggelinding. Baterai menyimpan energi kimia; demikian pula makanan. Karet yang diregangkan memiliki energi potensial elastis. Buku di rak memiliki energi potensial terkait posisi dalam sistem buku–Bumi. Energi dapat dipindahkan melalui usaha, pemanasan, atau radiasi. Gagasan energi membantu menelusuri perubahan yang tidak selalu terlihat langsung.'),
('Bagaimana energi berubah bentuk?','Apakah baterai senter menyimpan cahaya?', 'Energi kimia baterai dipindahkan melalui proses listrik ketika rangkaian terhubung. Lampu kemudian menghasilkan cahaya dan menjadi hangat. Kipas menghasilkan gerak sekaligus bunyi dan pemanasan. Sumber berbeda dari bentuk energi: Matahari adalah sumber, sedangkan cahaya membawa energi dari Matahari ke Bumi.'),
('Apakah energi hilang ketika benda berhenti?','Mengapa tangan menghangat setelah digosok?', 'Gesekan dapat mengurangi energi gerak dan menambah energi internal benda serta lingkungannya. Energi tidak musnah hanya karena tidak lagi terlihat sebagai gerak. Kenaikan suhu dapat kecil sehingga tidak terasa. Energi total sistem terisolasi tetap; energi pada satu benda dapat berubah karena berpindah ke benda lain.'),
('Mengapa perlu hemat energi?','Jika energi tidak musnah, mengapa tidak menggunakannya sesuka hati?', 'Tidak semua energi yang menyebar mudah dipakai kembali untuk tujuan kita. Penyediaan energi memerlukan bahan, biaya, dan proses yang dapat memengaruhi lingkungan. Mematikan alat saat tidak diperlukan mengurangi pemakaian yang tidak bermanfaat. Gunakan penerangan sesuai kebutuhan dan manfaatkan cahaya alami jika memadai. Daya secara sederhana menyatakan seberapa cepat energi dipindahkan atau digunakan; pembahasannya tidak memerlukan perhitungan di sini.')],
[['senter','Senter','Dari mana cahaya senter berasal?', 'Energi kimia baterai dipindahkan melalui proses listrik. Lampu menghasilkan cahaya sekaligus pemanasan alat dan lingkungan.'],['kipas','Kipas','Apakah seluruh keluaran kipas berupa gerak?', 'Gerak baling-baling dan udara disertai bunyi serta pemanasan. Keluaran yang tidak kita inginkan bukan berarti energi musnah.'],['tangan','Menggosok tangan','Apa hubungan gerak dengan rasa hangat?', 'Kerja otot memungkinkan gerak. Gesekan antarpermukaan tangan meningkatkan energi internal dan dapat membuat tangan lebih hangat.']],
['Geser buku, angkat sedikit, lalu tahan diam. Bandingkan keadaan yang disertai perpindahan dengan menahan buku diam.','Gosok telapak tangan dengan lembut. Catat pengamatan dan jelaskan perubahan energinya. Hentikan jika tidak nyaman.'],
[['Baterai habis berarti energinya musnah. Benarkah?','Energi sudah berpindah dan berubah, antara lain menjadi cahaya serta energi internal. Baterai tidak lagi dapat memasok energi listrik seperti semula.'],['Apa perbedaan sumber dan bentuk energi pada cahaya Matahari?','Matahari adalah sumber; cahaya merupakan pembawa energi dari sumber tersebut.']],
'Pilih satu alat di rumah dan jelaskan perubahan energinya kepada siswa MI.',PHYS)
add('suhu','Suhu Kalor dan Perpindahan Panas','Fisika',
'Sendok logam terasa lebih dingin daripada sendok kayu di ruangan yang sama. Apakah suhu logam pasti lebih rendah?',
['Membedakan suhu dari perpindahan energi karena perbedaan suhu.','Menjelaskan konduksi, konveksi, dan radiasi dalam kehidupan.'],[
('Apa yang dirasakan tangan?','Apakah sentuhan merupakan termometer yang andal?', 'Suhu menyatakan keadaan termal suatu benda dan diukur dengan termometer. Tangan merasakan pengaruh perpindahan energi, bukan hanya nilai suhu. Logam dapat menghantarkan energi dari tangan lebih cepat daripada kayu, sehingga terasa lebih dingin walaupun keduanya telah berada pada suhu ruang yang sama. Bandingkan menggunakan alat bila hendak memastikan suhu.'),
('Apa yang dimaksud kalor?','Apakah kalor sama dengan suhu yang tinggi?', 'Kalor adalah energi yang berpindah karena perbedaan suhu. Secara spontan, energi berpindah dari benda bersuhu lebih tinggi ke benda bersuhu lebih rendah hingga mendekati kesetimbangan. Benda memiliki energi internal; kalor bukan zat panas yang tersimpan. Es dapat menerima energi dan mencair tanpa suhu langsung meningkat selama perubahan wujud berlangsung pada kondisi yang sesuai.'),
('Bagaimana energi merambat melalui bahan?','Mengapa gagang panci sering dibuat dari bahan berbeda?', 'Konduksi terjadi melalui interaksi di dalam bahan tanpa perpindahan bahan secara keseluruhan. Logam umumnya menghantarkan panas lebih baik daripada kayu atau plastik. Gagang yang memperlambat perpindahan panas mengurangi laju pemanasan tangan. Isolator memperlambat perpindahan energi, bukan menghalanginya secara mutlak.'),
('Apakah panas selalu membutuhkan sentuhan?','Bagaimana sinar Matahari menghangatkan Bumi?', 'Pada konveksi, energi terbawa gerak fluida, seperti air atau udara. Gerak tersebut dapat terjadi karena perbedaan kerapatan maupun karena kipas atau pompa. Radiasi memindahkan energi melalui gelombang elektromagnetik dan tidak memerlukan zat perantara. Dalam satu peristiwa, beberapa mekanisme dapat berlangsung bersama; membedakannya tidak berarti selalu hanya ada satu mekanisme.'),
('Aplikasi di sekitar kita','Mengapa jaket menghangatkan tubuh dan termos memperlambat perubahan suhu?', 'Jaket membantu mengurangi laju pelepasan energi tubuh; jaket tidak otomatis menghasilkan panas sendiri. Termos dirancang memperlambat beberapa jalur perpindahan energi. Saat cuaca panas, bahan dan ventilasi dipilih untuk membantu tubuh melepaskan energi dengan aman. Hindari menguji benda panas melalui sentuhan langsung.')],
[['konduksi','Konduksi','Mengapa bagian sendok yang tidak tercelup dapat menghangat?', 'Energi berpindah melalui bahan sendok dari bagian lebih hangat menuju bagian lebih dingin. Bahan sendok tidak mengalir dari satu ujung ke ujung lain.'],['konveksi','Konveksi','Apa yang bergerak pada air yang bersirkulasi?', 'Air sebagai fluida berpindah tempat dan membawa energi. Diagram menunjukkan pola ideal; aliran nyata dipengaruhi wadah dan kondisi pemanasan.'],['radiasi','Radiasi','Bagaimana energi menyeberangi ruang hampa?', 'Radiasi elektromagnetik dapat membawa energi tanpa medium material. Matahari menghangatkan Bumi terutama melalui jalur ini.']],
['Bandingkan sendok logam dan benda kayu pada suhu ruang yang sama. Tuliskan sensasinya tanpa menyatakan bahwa sensasi pasti sama dengan suhu.','Pilih termos, gagang panci, atau jaket. Jelaskan fungsi bahannya dalam memperlambat perpindahan energi. Jangan menggunakan air panas.'],
[['Baju hangat menciptakan panas. Setujukah Anda?','Umumnya baju membantu mengurangi kehilangan energi dari tubuh. Tubuh menghasilkan energi termal melalui proses metabolisme.'],['Energi dari Matahari sampai ke Bumi melalui konveksi. Benarkah?','Tidak. Ruang antarbenda langit tidak berisi aliran udara yang membawa energi itu; radiasi dapat merambat melalui ruang hampa.']],
'Bagaimana mengoreksi “logam selalu lebih dingin” dengan bahasa yang mudah dipahami anak?',PHYS)
add('bunyi','Gelombang dan Bunyi','Fisika',
'Ketika riak bergerak di permukaan air, apakah seluruh air berjalan bersama riak menuju tepi?',
['Menjelaskan gelombang sebagai perambatan gangguan yang membawa energi.','Membedakan tinggi-rendah nada dan kuat-lemah bunyi.'],[
('Apa yang merambat?','Mengapa benda terapung dapat naik turun saat riak lewat?', 'Gelombang merupakan gangguan yang merambat dan membawa energi. Pada model sederhana, bagian medium bergetar di sekitar kedudukan awal; medium tidak seluruhnya berpindah bersama gelombang. Riak air nyata lebih kompleks daripada gerak naik turun saja. Representasi tali membantu menunjukkan perbedaan gerak gangguan dan gerak bagian medium.'),
('Dari mana bunyi berasal?','Apa yang terjadi pada penggaris yang dijentik perlahan?', 'Sumber bunyi bergetar dan menghasilkan perubahan tekanan pada medium, misalnya udara. Perubahan itu merambat hingga menggetarkan bagian telinga. Bunyi dapat merambat melalui gas, cairan, dan padatan, tetapi tidak melalui ruang hampa. Pola rapatan-renggangan mewakili gelombang bunyi di udara; gambar gelombang bergelombang bukan bentuk lintasan suara yang melayang.'),
('Apakah nada tinggi selalu lebih keras?','Dua orang menyanyikan nada sama; mengapa salah satunya terdengar lebih kuat?', 'Tinggi-rendah nada terutama berkaitan dengan frekuensi getaran. Kuat-lemah bunyi berkaitan dengan intensitas dan amplitudo, serta dipengaruhi jarak dan kondisi pendengaran. Pada perbandingan model, bedakan frekuensi dari amplitudo. Bunyi bernada tinggi dapat pelan, dan bunyi bernada rendah dapat kuat.'),
('Mengapa suara terdengar kembali?','Apa bedanya pantulan bunyi dengan sumber baru?', 'Bunyi dapat dipantulkan permukaan. Gema yang terpisah jelas terjadi bila pantulan tiba cukup terlambat; pantulan berdekatan dapat bercampur menjadi dengung. Bahan penyerap membantu mengurangi pantulan di ruangan. Bunyi juga dapat dipakai untuk komunikasi dan penginderaan. Jaga volume dan hindari bunyi kuat dekat telinga.')],
[['rendah','Nada rendah','Apa ciri getarannya dibandingkan nada tinggi?', 'Dalam selang waktu sama, getarannya lebih sedikit. Diagram adalah representasi perubahan tekanan, bukan lintasan partikel udara.'],['tinggi','Nada tinggi','Apakah amplitudo harus lebih besar?', 'Tidak. Frekuensi dapat bertambah tanpa memperbesar amplitudo. Tinggi nada dibedakan dari kuat-lemah bunyi.'],['kuat','Bunyi lebih kuat','Jika frekuensi tetap, apa yang berubah pada model?', 'Amplitudo diperbesar. Untuk kondisi dan medium yang dibandingkan sama, ini mewakili perubahan kuat bunyi, bukan perubahan nada.']],
['Jentik pelan ujung penggaris yang menjorok sedikit dari meja sambil menahan bagian lainnya. Amati getarannya. Jangan arahkan ke wajah.','Bandingkan gambar gelombang pada eksplorasi. Jelaskan perubahan nada dan kuat bunyi tanpa mencoba bunyi keras.'],
[['Bunyi dapat merambat dari dua benda melalui ruang hampa. Benarkah?','Tidak dalam pengertian gelombang bunyi mekanik; bunyi membutuhkan medium.'],['Memperkuat suara selalu menaikkan nadanya. Benarkah?','Tidak. Kuat bunyi dan tinggi nada berkaitan dengan sifat getaran yang berbeda.']],
'Bagian mana dari gambar gelombang yang berpotensi menyesatkan siswa tentang gerak udara?',PHYS)
add('cahaya','Cahaya dan Sifat Sifatnya','Fisika',
'Mengapa buku dapat terlihat meskipun tidak menghasilkan cahaya sendiri?',
['Menjelaskan penglihatan melalui cahaya yang masuk ke mata.','Menghubungkan perambatan, pemantulan, dan pembiasan dengan fenomena sehari-hari.'],[
('Bagaimana kita melihat?','Apakah mata mengirim cahaya ke buku?', 'Benda dapat terlihat ketika cahaya dari benda masuk ke mata. Lampu menghasilkan cahaya; buku umumnya memantulkan sebagian cahaya yang mengenainya. Tanpa cahaya yang cukup masuk ke mata, benda sulit dilihat. Diagram arah cahaya harus menunjukkan sumber menuju benda, lalu menuju mata.'),
('Mengapa terbentuk bayangan gelap?','Apakah semua bahan menghalangi cahaya dengan cara sama?', 'Dalam medium seragam, cahaya dimodelkan merambat lurus. Benda tidak tembus cahaya menghalangi sebagian jalur sehingga terbentuk bayangan. Bahan bening meneruskan banyak cahaya; bahan tembus cahaya yang menghamburkan cahaya menghasilkan pandangan kabur. Ukuran bayangan berubah bersama posisi sumber, benda, dan layar. Berkas sinar adalah model untuk membantu menelusuri arah.'),
('Mengapa terlihat pantulan?','Apa perbedaan permukaan cermin dan kertas?', 'Keduanya memantulkan cahaya. Cermin memantulkan secara teratur sehingga dapat membentuk bayangan yang jelas, sedangkan permukaan kasar menyebarkan pantulan ke berbagai arah. Itulah sebabnya buku dapat dilihat dari beberapa posisi. Bayangan pada cermin tidak berupa benda yang tersimpan di belakang kaca.'),
('Mengapa sedotan tampak bengkok?','Apakah sedotan benar-benar patah saat dicelupkan?', 'Arah cahaya dapat berubah saat melintasi dua medium dengan sifat optik berbeda, seperti air dan udara. Pembiasan menyebabkan posisi bagian terendam tampak bergeser. Lensa menggunakan pembiasan untuk mengubah arah cahaya. Cahaya yang datang tepat tegak lurus batas medium tidak selalu membelok meski kelajuan rambatnya berubah.'),
('Aplikasi dan warna','Mengapa kita tidak boleh mengarahkan cahaya kuat ke mata?', 'Mata perlu dilindungi dari sumber sangat terang. Gunakan senter biasa dan pantulan tidak menyilaukan. Warna benda dipengaruhi cahaya yang datang serta bagian cahaya yang dipantulkan atau diteruskan. Pelangi melibatkan pembiasan, pemantulan internal, dan pemisahan warna oleh tetes air; bukan lukisan warna tetap di langit.')],
[['lihat','Melihat benda','Ke arah mana panah cahaya harus menunjuk?', 'Cahaya dari sumber mengenai benda, lalu sebagian cahaya yang dipantulkan masuk ke mata. Mata tidak perlu mengirim sinar untuk melihat.'],['bayangan','Bayangan gelap','Mengapa ada bagian layar yang tidak tersinari?', 'Benda tidak tembus cahaya menghalangi sebagian jalur. Diagram menyederhanakan sumber sebagai sumber kecil.'],['bias','Pembiasan','Apa yang berubah ketika cahaya melintasi batas miring?', 'Arah rambat dapat berubah. Sedotan tetap lurus secara fisik, tetapi penampakan bagian di air dapat bergeser.']],
['Amati bayangan buku dengan senter biasa atau cahaya lampu. Ubah jarak benda dari layar; catat apa yang berubah. Jangan arahkan senter ke mata.','Gambar panah untuk menjelaskan bagaimana Anda dapat melihat halaman buku.'],
[['Benda yang tidak bercahaya tidak bisa terlihat. Benarkah?','Benda dapat terlihat karena memantulkan cahaya dari sumber lain ke mata.'],['Sedotan di dalam air patah karena dibias. Benarkah?','Yang berubah adalah arah cahaya dan penampakannya, bukan bentuk fisik sedotan.']],
'Bagaimana menjelaskan penglihatan tanpa membuat siswa mengira mata memancarkan sinar?',PHYS)
add('listrik','Listrik dan Magnet','Fisika',
'Mengapa lampu senter mati ketika sakelarnya dibuka, walaupun baterainya masih ada?',
['Menjelaskan perlunya lintasan tertutup pada rangkaian sederhana.','Membedakan interaksi listrik dan magnet serta menerapkan penggunaan aman.'],[
('Apakah listrik selalu mengalir?','Apa bedanya penggaris yang menarik potongan kertas dan lampu senter menyala?', 'Muatan listrik dapat menimbulkan tarikan atau tolakan. Penggaris plastik yang digosok dapat bermuatan dan menarik kertas melalui interaksi elektrostatik. Ini berbeda dari arus listrik yang berkaitan dengan aliran muatan dalam rangkaian. Tarikan pada kertas tidak berarti semua benda yang menarik adalah magnet.'),
('Apa syarat lampu dapat menyala?','Apakah satu kabel dari baterai ke lampu sudah cukup?', 'Rangkaian sederhana memerlukan lintasan konduktif tertutup yang menghubungkan kedua terminal sumber melalui komponen. Sakelar membuka atau menutup lintasan. Baterai memindahkan energi melalui proses listrik; bukan menyuntikkan cahaya ke kabel. Muatan tidak habis dikonsumsi lampu. Pada demonstrasi, gunakan hanya model atau baterai rendah tegangan yang sesuai.'),
('Satu jalur atau beberapa cabang?','Mengapa lampu rumah dapat dinyalakan terpisah?', 'Pada rangkaian seri, komponen tersusun pada satu jalur sehingga putusnya jalur dapat memadamkan semuanya. Pada paralel, cabang memberi lintasan lain, sehingga satu cabang dapat tetap bekerja ketika cabang lain dibuka. Perbandingan kecerahan bergantung sumber dan komponen; jangan menganggap semua gambar rangkaian menunjukkan kecerahan yang sama.'),
('Bahan dan keselamatan','Apakah kabel berlapis plastik hanya agar tampak rapi?', 'Logam penghantar di dalam kabel menyediakan jalur arus, sedangkan lapisan isolator membantu mencegah kontak tidak sengaja. Air biasa dapat menghantarkan listrik karena mengandung ion, sehingga tangan basah berbahaya di dekat peralatan listrik. Jangan memasukkan benda ke stopkontak, membuka alat tersambung listrik, atau menghubungsingkat baterai.'),
('Bagaimana magnet berinteraksi?','Apakah semua logam tertarik magnet?', 'Tidak. Besi dan beberapa bahan lain dapat tertarik kuat, tetapi banyak logam tidak. Kutub sejenis tolak-menolak dan kutub berbeda tarik-menarik. Memotong magnet tidak memisahkan kutub utara saja dari selatan saja; potongan tetap memiliki dua kutub. Elektromagnet menghubungkan arus listrik dengan kemagnetan. Kompas merespons medan magnet, termasuk medan Bumi.')],
[['buka','Sakelar terbuka','Apakah ada lintasan lengkap melalui lampu?', 'Lintasan terputus sehingga lampu dalam model tidak menyala. Diagram menunjukkan rangkaian sederhana, bukan petunjuk menyambung listrik rumah.'],['tutup','Sakelar tertutup','Apa yang berubah ketika sakelar ditutup?', 'Terbentuk jalur tertutup melalui baterai, kabel, dan lampu. Energi listrik dapat dipindahkan ke lampu.'],['magnet','Magnet','Bagaimana kutub sejenis berinteraksi?', 'Kutub sejenis menolak, berbeda jenis menarik. Simbol U dan S menandai kutub magnet, bukan muatan listrik positif dan negatif.']],
['Bandingkan model sakelar terbuka dan tertutup. Gambar jalur yang menghubungkan kedua terminal baterai melalui lampu.','Susun pesan keselamatan untuk siswa MI berdasarkan kabel rusak dan tangan basah. Tidak perlu menggunakan listrik sungguhan.'],
[['Lampu memakan muatan sampai habis. Benarkah?','Tidak. Energi dipindahkan; muatan tidak habis dikonsumsi lampu dalam rangkaian.'],['Semua logam tertarik magnet. Benarkah?','Tidak. Sifat magnetik bergantung bahannya.']],
'Bagaimana memastikan kegiatan listrik siswa aman sekaligus memperlihatkan lintasan tertutup?',PHYS)
add('keanekaragaman','Keanekaragaman dan Karakteristik Makhluk Hidup','Biologi',
'Api dapat membesar dan memerlukan bahan bakar. Apakah itu membuat api termasuk makhluk hidup?',
['Menilai ciri kehidupan sebagai gabungan karakteristik.','Mengelompokkan organisme berdasarkan dasar yang jelas.'],[
('Satu ciri atau gabungan ciri?','Apakah semua yang bergerak pasti hidup?', 'Mobil bergerak dan api membesar, tetapi keduanya tidak memiliki organisasi sel serta proses kehidupan seperti organisme. Makhluk hidup tersusun atas sel, menggunakan energi, mengatur keadaan internal, merespons lingkungan, tumbuh dan berkembang; garis keturunannya dapat bereproduksi. Ciri tidak harus tampak sekaligus pada satu pengamatan. Individu yang tidak menghasilkan keturunan tetap makhluk hidup.'),
('Hidup tidak selalu tampak aktif','Apakah biji kering pasti benda mati?', 'Biji yang masih viabel dapat berada pada keadaan dorman dengan aktivitas rendah dan berkecambah ketika syarat sesuai. Sebaliknya, gerak daun tertiup angin bukan bukti tunggal bahwa tumbuhan hidup. Perlu membedakan proses organisme dari pengaruh luar. Virus merupakan kasus khusus yang tidak dibahas melalui daftar ciri sederhana saja.'),
('Mengapa organisme dikelompokkan?','Apakah satu dasar pengelompokan cocok untuk semua tujuan?', 'Pengelompokan membantu mengenali persamaan, perbedaan, dan hubungan. Untuk kegiatan awal, gunakan ciri yang dapat diamati: daun, penutup tubuh, atau keberadaan tulang belakang berdasarkan sumber yang sesuai. Kelompok berdasarkan habitat berguna untuk tujuan tertentu, tetapi tidak otomatis menggambarkan hubungan kekerabatan. Jamur bukan tumbuhan; jamur memperoleh nutrien dengan menyerap bahan organik.'),
('Keanekaragaman di sekitar sekolah','Apakah semua organisme dari jenis yang sama selalu identik?', 'Variasi dapat ditemukan antarindividu, antarjenis, dan antarekosistem. Persamaan nama sehari-hari belum tentu menjamin jenis yang sama. Dokumentasikan ciri tanpa memberi nama ilmiah secara menebak. Keanekaragaman berhubungan dengan fungsi ekosistem, sumber pangan, dan pengetahuan lokal. Pengamatan tidak perlu merusak sarang atau mengambil organisme.'),
('Menjaga ketepatan pengamatan','Bagaimana jika sebuah objek belum dapat kita tentukan?', 'Catat ketidakpastian dan cari sumber pembanding. Menyebut “belum teridentifikasi” lebih tepat daripada memaksa nama. Ilustrasi bukan sampel representatif seluruh organisme. Dasar klasifikasi harus disebut agar orang lain dapat memahami alasan suatu objek dimasukkan dalam kelompok tertentu.')],
[['api','Api','Apakah membesar cukup menjadi bukti hidup?', 'Api dapat menyebar tetapi tidak tersusun atas sel sebagai organisme. Satu kemiripan perilaku tidak cukup untuk menetapkan kehidupan.'],['biji','Biji','Apakah tidak bergerak berarti mati?', 'Biji yang viabel tetap hidup walaupun dorman. Kondisi perkecambahan dan keberadaan embrio membantu menjelaskannya.'],['jamur','Jamur','Apakah semua organisme yang menetap adalah tumbuhan?', 'Tidak. Jamur merupakan kelompok berbeda; cara memperoleh nutriennya berbeda dari tumbuhan hijau yang berfotosintesis.']],
['Catat tiga organisme yang dapat diamati di sekitar kelas atau melalui foto. Pilih satu dasar pengelompokan yang dapat dijelaskan.','Bandingkan api dan biji menggunakan beberapa karakteristik kehidupan, bukan hanya gerak.'],
[['Organisme yang tidak bereproduksi pasti bukan makhluk hidup. Benarkah?','Tidak. Ciri reproduksi dilihat pada keberlanjutan jenis; tidak semua individu bereproduksi.'],['Habitat sama berarti kelompok kekerabatan sama. Benarkah?','Tidak. Organisme dengan asal dan struktur berbeda dapat menghuni habitat yang sama.']],
'Bagaimana membantu siswa mengelompokkan organisme tanpa menghafal nama yang belum dipahami?',BIO)
add('tumbuhan','Struktur dan Fungsi Tumbuhan','Biologi',
'Tanaman bertambah besar. Apakah semua bahan pembentuk tubuhnya berasal dari tanah?',
['Menghubungkan bagian tumbuhan dengan fungsi yang saling mendukung.','Menjelaskan peran cahaya, air, dan udara dalam kehidupan tumbuhan.'],[
('Bagian tumbuhan bekerja bersama','Apakah akar hanya berfungsi menahan tanaman?', 'Pada banyak tumbuhan, akar menyerap air dan mineral serta menambatkan tubuh. Batang menyangga dan menyediakan jalur pengangkutan. Daun menjadi tempat utama fotosintesis pada tumbuhan hijau berdaun. Struktur dapat mengalami modifikasi, misalnya akar penyimpan makanan atau batang penyimpan air. Tidak semua tumbuhan memiliki bagian yang sama mencoloknya.'),
('Dari mana tumbuhan memperoleh bahan pembentuk tubuh?','Apakah pupuk sama dengan makanan siap pakai?', 'Dalam fotosintesis, tumbuhan hijau menggunakan energi cahaya untuk membentuk bahan organik dari air dan karbon dioksida. Karbon dioksida dari udara memberi bahan penting untuk pertambahan tubuh. Mineral dari tanah diperlukan tetapi bukan seluruh bahan makanan. Pupuk menyediakan unsur hara, bukan menggantikan kebutuhan cahaya, air, dan pertukaran gas.'),
('Air tidak berhenti di akar','Bagaimana air dapat sampai ke daun?', 'Jaringan pengangkut menghubungkan bagian tumbuhan. Xilem mengangkut air dan mineral; floem memindahkan hasil fotosintesis menuju bagian yang membutuhkan atau menyimpannya. Penguapan air melalui daun membantu proses pergerakan air. Stomata berperan dalam pertukaran gas dan pengaturan kehilangan air. Gambar panah merupakan penyederhanaan proses yang saling berkaitan.'),
('Apakah tumbuhan bernapas hanya malam hari?','Mengapa tumbuhan tetap membutuhkan energi saat tidak terkena cahaya?', 'Tumbuhan melakukan respirasi untuk menggunakan energi dari bahan organik sepanjang hidupnya, siang maupun malam. Fotosintesis bergantung cahaya yang memadai; respirasi tidak sama dengan fotosintesis yang dibalik sekadar menurut jam. Pertumbuhan tanaman tidak cukup dinilai dari tinggi: batang sangat memanjang di tempat gelap dapat menandakan etiolasi, bukan tanaman lebih sehat.'),
('Bunga buah dan biji','Apakah buah terbentuk tanpa kaitan dengan bunga?', 'Pada tumbuhan berbunga, bunga berperan dalam reproduksi. Penyerbukan berbeda dari pembuahan. Setelah proses yang sesuai, bakal biji berkembang menjadi biji dan bagian bunga dapat berkembang menjadi buah. Contoh bunga dan buah setempat membantu menghubungkan struktur dengan fungsi tanpa menganggap semua tumbuhan bereproduksi melalui bunga.')],
[['akar','Akar dan batang','Dari mana air masuk dan melalui bagian mana air bergerak?', 'Akar menyerap air; jaringan pengangkut menghubungkan akar, batang, dan daun. Panah biru menunjukkan jalur air yang disederhanakan.'],['daun','Daun','Apa yang masuk ke proses fotosintesis?', 'Cahaya menyediakan energi; air dan karbon dioksida menyediakan bahan. Tumbuhan membentuk bahan organik, bukan hanya menyerap makanan dari tanah.'],['bunga','Bunga dan biji','Mengapa bunga berhubungan dengan generasi baru?', 'Pada tumbuhan berbunga, bunga memungkinkan proses reproduksi yang menghasilkan biji setelah penyerbukan dan pembuahan yang sesuai.']],
['Amati satu tanaman tanpa mencabutnya. Buat gambar berlabel akar yang diperkirakan, batang, dan daun; bedakan bagian yang benar-benar terlihat dari yang diinferensikan.','Analisis pernyataan “pupuk adalah satu-satunya makanan tumbuhan”. Perbaiki menggunakan peran air, udara, mineral, dan cahaya.'],
[['Tanaman yang paling tinggi selalu paling sehat. Benarkah?','Tidak. Tinggi perlu dibaca bersama warna daun, kekuatan batang, dan kondisi tumbuh.'],['Tumbuhan tidak melakukan respirasi pada siang hari. Benarkah?','Tumbuhan melakukan respirasi siang dan malam.']],
'Bagaimana menggambar tumbuhan agar anak tidak menyimpulkan seluruh makanannya berasal dari tanah?',BIO)
add('hewan','Struktur dan Fungsi Hewan','Biologi',
'Ikan, burung, dan kucing menggunakan bagian tubuh berbeda. Bagaimana struktur itu membantu hidup di lingkungannya?',
['Menghubungkan struktur tubuh dengan cara hidup hewan.','Membedakan adaptasi, perubahan individu, dan tahap daur hidup.'],[
('Struktur mempunyai hubungan dengan fungsi','Apakah sayap hanya dapat dimengerti sebagai alat untuk terbang?', 'Struktur tubuh perlu ditelaah bersama fungsinya dan konteks jenis hewan. Sirip membantu ikan mengendalikan gerak di air; bentuk tubuh juga berpengaruh. Sayap burung memiliki variasi fungsi, dan sebagian burung tidak terbang. Kaki, paruh, gigi, atau penutup tubuh memberi petunjuk cara hidup tetapi tidak cukup untuk memastikan seluruh kebiasaan hewan.'),
('Bagaimana memperoleh makanan dan oksigen?','Apakah semua hewan air bernapas dengan insang?', 'Tidak. Ikan umumnya menggunakan insang untuk mengambil oksigen terlarut, sedangkan lumba-lumba dan paus menggunakan paru-paru serta bernapas di permukaan. Burung dan mamalia memiliki sistem pernapasan berbeda meskipun sama-sama mengambil oksigen dari udara. Hewan memperoleh bahan organik dari organisme lain, dengan variasi alat pencernaan sesuai jenisnya.'),
('Apa arti adaptasi?','Apakah hewan sengaja membentuk organ karena ingin bertahan?', 'Adaptasi mencakup karakteristik yang mendukung keberhasilan hidup dan reproduksi dalam lingkungan tertentu, dibentuk melalui proses evolusi antargenerasi. Bukan keputusan sadar individu untuk mengubah organ. Perilaku dan penyesuaian fisiologis individu dapat membantu menghadapi kondisi, tetapi tidak semua perubahan individu disebut adaptasi evolusioner. Gunakan ungkapan “struktur ini membantu” tanpa mengarang niat hewan.'),
('Daur hidup dan perubahan bentuk','Apakah anak hewan selalu menyerupai dewasa?', 'Kucing muda memiliki bentuk dasar mirip dewasa. Kupu-kupu melalui telur, larva, pupa, dan dewasa dengan perubahan bentuk jelas. Belalang tidak melalui pupa; nimfanya berkembang menuju dewasa. Pupa bukan benda mati. Telur, pertumbuhan, dan perubahan bentuk perlu dibahas sebagai proses organisme, bukan urutan gambar tanpa hubungan.'),
('Memeriksa generalisasi','Apakah semua hewan berkaki empat termasuk satu jenis kelompok dekat?', 'Ciri yang tampak membantu pengamatan tetapi klasifikasi perlu mempertimbangkan lebih dari satu ciri dan sumber ilmiah. Pengamatan hewan hendaknya tidak melukai, mengganggu sarang, atau menahan satwa. Foto dan diagram dapat menggantikan penangkapan hewan di kelas.')],
[['ikan','Ikan','Apa hubungan sirip dengan lingkungan air?', 'Sirip membantu arah dan kestabilan gerak. Insang mengambil oksigen yang terlarut dalam air; ikan tidak mengambil oksigen dari molekul air dengan memecahnya.'],['burung','Burung','Apa yang dapat disimpulkan dari paruh dan sayap?', 'Bentuk paruh berkaitan dengan cara memperoleh makanan dan sayap dengan berbagai fungsi. Satu bentuk tidak cukup memastikan seluruh perilaku.'],['kupu','Daur hidup','Apakah pupa merupakan hewan yang berhenti hidup?', 'Pupa merupakan tahap hidup dengan perubahan perkembangan. Organisme tidak berubah menjadi benda mati lalu hidup kembali.']],
['Bandingkan dua hewan setempat melalui foto atau pengamatan aman. Hubungkan satu struktur dengan fungsinya; tandai dugaan yang belum memiliki bukti.','Susun urutan daur hidup kupu-kupu dan bandingkan dengan belalang. Jelaskan peran tahap pupa.'],
[['Semua hewan air bernapas dengan insang. Benarkah?','Tidak. Mamalia air menggunakan paru-paru dan perlu memperoleh udara dari permukaan.'],['Hewan mengubah organ karena menginginkannya. Benarkah?','Tidak. Adaptasi evolusioner bukan perubahan organ melalui keinginan sadar individu.']],
'Bagaimana mengganti kalimat “burung membuat sayap agar dapat terbang” dengan penjelasan yang lebih tepat?',BIO)
add('manusia','Sistem Organ Manusia','Biologi',
'Setelah bergerak, napas dan denyut jantung lebih cepat. Mengapa dua sistem tubuh merespons kegiatan yang sama?',
['Menjelaskan hubungan organ dalam memenuhi kebutuhan tubuh.','Menghubungkan kebiasaan sehat dengan fungsi tubuh tanpa membuat diagnosis.'],[
('Tubuh bukan kumpulan organ terpisah','Mengapa makan saja tidak cukup tanpa bernapas?', 'Sel tubuh memerlukan bahan dan energi untuk bekerja. Sistem pencernaan mengolah makanan dan menyerap nutrien. Sistem pernapasan menyediakan pertukaran oksigen dan karbon dioksida, sedangkan peredaran darah menghubungkan organ dengan jaringan tubuh. Ketiganya saling mendukung; satu organ tidak menjalankan seluruh proses sendirian.'),
('Apa yang terjadi pada makanan?','Apakah semua makanan langsung menjadi darah?', 'Makanan mengalami pencernaan mekanik dan kimiawi sepanjang saluran tertentu. Sebagian besar penyerapan nutrien terjadi di usus halus, lalu nutrien dibawa melalui jalur peredaran yang sesuai. Usus besar berperan antara lain dalam penyerapan air dari sisa isi saluran dan pembentukan feses. Feses berbeda dari urine; pembentukan urine melibatkan ginjal yang menyaring darah dan mengatur keseimbangan tubuh.'),
('Bernapas dan respirasi berbeda pengertian','Apakah paru-paru mengubah udara menjadi energi?', 'Bernapas memindahkan udara masuk dan keluar. Pertukaran gas terjadi pada bagian halus paru-paru, sehingga oksigen masuk ke darah dan karbon dioksida keluar. Respirasi sel menggunakan proses kimia untuk melepaskan energi dari bahan organik. Pernapasan mendukungnya, tetapi udara bukan bahan yang berubah begitu saja menjadi energi.'),
('Apa yang diedarkan jantung?','Apakah darah hanya membawa oksigen?', 'Jantung memompa darah. Darah membawa gas, nutrien, zat sisa, dan berbagai komponen lain. Pembuluh nadi membawa darah menjauhi jantung; pembuluh balik membawanya menuju jantung. Pembeda ini lebih tepat daripada menghafal “nadi selalu kaya oksigen”, karena sirkulasi ke paru-paru memiliki pengecualian terhadap pola kandungan oksigen tersebut.'),
('Bergerak merasakan dan merespons','Mengapa tangan dapat bergerak terarah?', 'Sistem saraf menerima informasi dan mengoordinasi respons. Otot menarik tulang melalui perlekatannya untuk menghasilkan gerak pada sendi. Tulang juga menyangga dan melindungi organ. Tidur, makanan beragam, aktivitas fisik sesuai kemampuan, dan kebersihan mendukung tubuh. Pengamatan kelas tidak digunakan untuk menentukan penyakit atau membandingkan kesehatan individu secara sembarangan.')],
[['cerna','Pencernaan','Apa jalur makanan yang sebenarnya?', 'Makanan melalui saluran pencernaan. Nutrien yang telah sesuai bentuknya diserap, terutama di usus halus. Gambar adalah peta proses, bukan anatomi berskala.'],['napas','Pernapasan','Apa yang bertukar antara udara dan darah?', 'Oksigen masuk ke darah dan karbon dioksida dikeluarkan. Panah dua arah mewakili dua gas berbeda, bukan seluruh udara masuk ke darah.'],['darah','Peredaran','Mengapa darah menghubungkan banyak organ?', 'Darah mengantar oksigen dan nutrien ke jaringan serta membawa zat sisa ke organ pengeluaran. Sistem organ bekerja sebagai jaringan hubungan.']],
['Buat peta jalur dari makanan dan udara menuju kebutuhan sel. Gunakan kata “diserap”, “diangkut”, dan “dipakai” dengan jelas.','Amati perubahan napas setelah berjalan santai bila nyaman. Alternatifnya analisis kasus tertulis; kegiatan tidak wajib bagi yang perlu beristirahat dan bukan pemeriksaan kesehatan.'],
[['Pencernaan selesai seluruhnya di lambung. Benarkah?','Tidak. Usus halus mempunyai peran penting dalam pencernaan lanjutan dan penyerapan nutrien.'],['Darah hanya membawa oksigen. Benarkah?','Darah juga membawa nutrien, karbon dioksida, dan berbagai zat lainnya.']],
'Bagaimana menjelaskan hubungan pencernaan, pernapasan, dan peredaran melalui satu cerita sehari-hari?',BIO)
add('ekosistem','Ekosistem dan Interaksi Makhluk Hidup','Biologi',
'Jika serangga di kebun berkurang, apakah hanya burung pemakan serangga yang dapat terpengaruh?',
['Menjelaskan hubungan komponen biotik dan abiotik.','Membedakan aliran energi dan perputaran materi dalam ekosistem.'],[
('Apa yang membuat sebuah tempat menjadi ekosistem?','Apakah cukup hanya ada beberapa makhluk hidup?', 'Ekosistem mencakup organisme dan lingkungan fisiknya beserta interaksi. Cahaya, air, tanah, dan suhu merupakan komponen abiotik yang memengaruhi kehidupan. Satu organisme merupakan individu; sekumpulan organisme sejenis di wilayah dan waktu tertentu disebut populasi. Berbagai populasi yang berinteraksi membentuk komunitas.'),
('Siapa memperoleh energi dari siapa?','Ke arah mana panah pada rantai makanan menunjuk?', 'Produsen seperti tumbuhan menangkap energi cahaya dan membentuk bahan organik. Konsumen memperolehnya melalui makanan. Panah rantai makanan diarahkan dari organisme yang dimakan menuju pemakannya untuk menunjukkan perpindahan energi melalui makanan. Jaring-jaring makanan menghubungkan banyak jalur; satu konsumen dapat memakai lebih dari satu sumber makanan.'),
('Apakah semua hubungan berupa makan-dimakan?','Mengapa organisme dapat berebut tempat atau sumber daya?', 'Interaksi mencakup pemangsaan, kompetisi, dan berbagai hubungan antarjenis. Manfaat atau kerugian harus ditentukan dari hubungan spesifik dan bukti, bukan hanya karena dua organisme terlihat bersama. Penyerbuk dapat membantu reproduksi tumbuhan sambil memperoleh sumber makanan, tetapi tidak semua hubungan serangga dan bunga identik.'),
('Ke mana daun gugur pergi?','Apakah pengurai mengembalikan energi ke Matahari?', 'Pengurai memproses bahan organik dan membantu mengembalikan unsur hara ke lingkungan. Materi dapat digunakan kembali melalui daur, sedangkan energi mengalir dan akhirnya banyak menyebar sebagai energi termal. Energi tidak berputar kembali dalam siklus yang sama seperti materi. Tanpa pengurai, proses pengembalian nutrien akan terganggu.'),
('Apakah dampak perubahan selalu sederhana?','Dapatkah satu rantai makanan meramalkan seluruh kondisi kebun?', 'Perubahan satu komponen dapat memengaruhi komponen lain, tetapi dampaknya bergantung hubungan dan kondisi setempat. Pestisida, berkurangnya habitat, atau perubahan air perlu dibahas melalui data. Perilaku menjaga habitat dan mengurangi sampah dapat diawali di sekolah tanpa mengklaim satu kegiatan kecil menyelesaikan seluruh persoalan lingkungan.')],
[['rantai','Rantai makanan','Panah dari rumput ke belalang berarti apa?', 'Belalang memperoleh energi melalui makanan dari rumput. Panah menunjukkan arah perpindahan, bukan arah pemangsa menunjuk mangsa.'],['jaring','Jaring makanan','Apakah satu hewan selalu memiliki satu makanan?', 'Tidak. Beberapa jalur dapat terhubung. Model ini hanya contoh hubungan, bukan daftar lengkap organisme setempat.'],['urai','Penguraian','Apa yang kembali digunakan dan apa yang mengalir?', 'Unsur penyusun bahan dapat kembali ke lingkungan dan dimanfaatkan organisme. Energi banyak menyebar sebagai energi termal, bukan berputar kembali sebagai energi cahaya.']],
['Amati lingkungan sekolah atau foto kebun. Catat dua komponen biotik, dua abiotik, dan satu dugaan interaksi yang masih perlu bukti.','Buat rantai makanan sederhana dengan arah panah yang benar, lalu tambahkan satu jalur agar menjadi jaring.'],
[['Energi dan materi sama-sama berputar dengan pola identik. Benarkah?','Tidak. Materi mengalami daur; energi mengalir dan menyebar, sehingga perlu masukan energi.'],['Dua organisme berdekatan pasti saling menguntungkan. Benarkah?','Kedekatan saja belum menunjukkan bentuk hubungan atau dampaknya.']],
'Kesalahan panah apa yang paling mungkin terjadi saat siswa menggambar rantai makanan?',BIO)
add('bumi','Bumi Cuaca dan Perubahan Lingkungan','Bumi dan Antariksa',
'Hari ini hujan deras. Apakah satu hari hujan sudah cukup untuk menjelaskan iklim suatu wilayah?',
['Membedakan cuaca dari pola iklim.','Menghubungkan daur air, kondisi permukaan, dan dampak perubahan lingkungan.'],[
('Bumi sebagai tempat yang saling terhubung','Apakah air, udara, tanah, dan organisme bekerja sendiri-sendiri?', 'Batuan dan tanah, air, atmosfer, serta kehidupan saling memengaruhi. Air mengubah permukaan melalui aliran dan erosi; tumbuhan memengaruhi tanah serta pertukaran air. Model lapisan Bumi membantu mengenali kerak, mantel, dan inti. Mantel bukan lautan cair seragam; sebagian besar bersifat padat yang dapat mengalir sangat lambat dalam skala geologi.'),
('Apa bedanya cuaca dan iklim?','Mengapa kabar suhu hari ini berbeda dari pernyataan iklim?', 'Cuaca menggambarkan keadaan atmosfer pada tempat dan waktu tertentu, seperti hujan, angin, dan suhu. Iklim mencakup pola statistik cuaca dalam jangka panjang. Satu hari dingin tidak cukup menyangkal tren pemanasan jangka panjang; satu hari panas juga tidak sendirian membuktikan tren. Gunakan catatan yang sesuai panjang waktu dan wilayah.'),
('Dari mana hujan berasal?','Apakah awan adalah kumpulan uap air tak tampak saja?', 'Air menguap dari permukaan dan juga dilepas tumbuhan. Uap air dapat mengembun membentuk tetes kecil atau kristal es penyusun awan. Tetes atau partikel es dapat tumbuh dan menghasilkan presipitasi. Air kemudian meresap, mengalir, tersimpan, atau kembali menguap. Daur ini bukan satu urutan tunggal yang harus dilalui setiap tetes air.'),
('Mengapa hujan yang sama dapat berdampak berbeda?','Apa hubungan permukaan tertutup, drainase, dan banjir?', 'Dampak hujan dipengaruhi intensitas dan durasi, kapasitas aliran, kondisi tanah, penggunaan lahan, dan letak wilayah. Permukaan tertutup dapat mengurangi resapan dan menambah limpasan. Tidak semua banjir disebabkan satu faktor. Penghijauan, pengelolaan sampah dan drainase perlu disesuaikan masalah setempat.'),
('Perubahan iklim dan tindakan','Apakah efek rumah kaca sepenuhnya buruk?', 'Efek rumah kaca alami membantu menjaga kondisi Bumi. Peningkatan gas rumah kaca mengubah keseimbangan energi dan mendorong pemanasan. Lubang ozon merupakan persoalan berbeda dari penguatan efek rumah kaca. Tindakan mengurangi emisi dan menyesuaikan diri terhadap dampak perlu dibedakan, walaupun keduanya dapat saling mendukung.')],
[['uap','Penguapan','Ke mana air yang tidak terlihat lagi berpindah?', 'Sebagian air berpindah ke atmosfer sebagai uap. Tumbuhan juga berperan dalam pertukaran air dengan atmosfer.'],['awan','Awan dan hujan','Apa yang membuat awan dapat terlihat?', 'Tetes air sangat kecil dan kristal es menghamburkan cahaya. Uap air sendiri tidak terlihat.'],['resap','Resapan dan limpasan','Apakah seluruh air hujan langsung kembali ke laut?', 'Sebagian meresap atau tersimpan, sebagian mengalir di permukaan. Jalurnya bergantung kondisi tanah dan lingkungan.']],
['Buat catatan cuaca hari ini: waktu, kondisi awan, dan hujan jika ada. Jelaskan mengapa catatan satu hari tidak cukup untuk menyimpulkan iklim.','Bandingkan gambar permukaan tanah bervegetasi dan permukaan tertutup. Susun dugaan jalur air hujan serta faktor lain yang perlu diperiksa.'],
[['Awan tersusun hanya dari uap air yang terlihat. Benarkah?','Awan tampak karena tetes air kecil atau kristal es; uap air tidak terlihat.'],['Satu hari hujan menjelaskan iklim Jambi. Benarkah?','Tidak. Iklim memerlukan pola data jangka panjang yang mewakili wilayah.']],
'Bagaimana membahas peristiwa banjir tanpa menyederhanakannya menjadi satu penyebab?',('NASA. Earth Science.','https://science.nasa.gov/earth/'))
add('antariksa','Tata Surya dan Benda Langit','Bumi dan Antariksa',
'Matahari tampak bergerak di langit setiap hari. Apakah itu berarti Matahari mengelilingi Bumi sekali sehari?',
['Membedakan rotasi, revolusi, dan perubahan penampakan Bulan.','Menggunakan model tata surya dengan menyebut keterbatasan skalanya.'],[
('Apa saja anggota tata surya?','Apakah semua benda langit menghasilkan cahaya sendiri?', 'Matahari adalah bintang yang menjadi sumber utama energi cahaya tata surya. Delapan planet mengorbit Matahari; benda lain meliputi satelit alami, asteroid, komet, dan planet katai. Bulan terlihat terutama karena memantulkan cahaya Matahari. Tata surya merupakan bagian kecil dari galaksi, bukan nama lain untuk seluruh alam semesta.'),
('Mengapa terjadi siang dan malam?','Apa yang berubah saat sebuah tempat masuk sisi Bumi yang tidak tersinari?', 'Bumi berotasi pada sumbunya. Pada waktu yang sama, bagian yang menghadap Matahari mengalami siang dan sisi lain malam. Gerak harian Matahari yang tampak terutama terkait rotasi Bumi, bukan bukti Matahari mengorbit Bumi setiap hari. Peta bola dan sumber lampu membantu menelusuri pencahayaan.'),
('Apakah revolusi sama dengan rotasi?','Mengapa pergantian musim tidak cukup dijelaskan oleh jauh-dekat Matahari?', 'Revolusi Bumi adalah peredaran mengelilingi Matahari. Kemiringan sumbu dan perubahan orientasi pencahayaan selama revolusi berperan besar pada musim tahunan, terutama di lintang sedang dan tinggi. Bukan karena Bumi sekadar lebih dekat ke Matahari. Musim hujan dan kemarau di Indonesia juga berkaitan dengan pola sirkulasi atmosfer dan laut, sehingga tidak identik dengan empat musim.'),
('Mengapa bentuk Bulan tampak berubah?','Apakah sabit selalu terjadi karena bayangan Bumi menutup Bulan?', 'Sebagian permukaan Bulan diterangi Matahari. Ketika Bulan mengorbit Bumi, bagian terang yang terlihat dari Bumi berubah sehingga muncul fase. Bayangan Bumi menutupi Bulan saat gerhana Bulan, bukan penyebab semua fase. Gerhana tidak terjadi setiap bulan karena bidang orbit Bulan miring terhadap bidang orbit Bumi.'),
('Apa yang tidak ditunjukkan model?','Apakah jarak planet pada poster selalu berskala?', 'Ukuran benda dan jarak orbit sangat berbeda, sehingga model kelas umumnya tidak berskala pada keduanya sekaligus. Warna dan lintasan juga dapat disederhanakan. Gunakan model untuk hubungan yang dituju, lalu jelaskan batasnya. Jangan melihat Matahari langsung atau menggunakan alat optik tanpa prosedur dan pelindung khusus yang sesuai.')],
[['rotasi','Siang dan malam','Bagian mana dari Bumi yang menerima cahaya?', 'Sisi yang menghadap sumber mengalami siang; rotasi mengubah tempat yang berada pada sisi tersebut. Ukuran dan jarak tidak berskala.'],['revolusi','Revolusi','Apa yang bergerak mengelilingi apa?', 'Bumi mengorbit Matahari. Diagram pandangan atas tidak dipakai untuk menjelaskan detail kemiringan sumbu atau seluruh mekanisme musim.'],['bulan','Fase Bulan','Apakah Bumi harus menutupi Bulan agar tampak sabit?', 'Tidak. Perubahan posisi Bulan membuat kita melihat bagian berbeda dari sisi yang diterangi Matahari. Diagram yang ditampilkan merupakan ikon penampakan fase, bukan geometri orbit.']],
['Gunakan bola dan sumber cahaya tetap, atau gambar model. Tandai satu lokasi dan jelaskan kapan lokasi itu mengalami siang dan malam.','Bandingkan gambar fase dengan gerhana. Tuliskan perbedaan penyebabnya dan satu keterbatasan model kelas.'],
[['Semua fase Bulan disebabkan bayangan Bumi. Benarkah?','Tidak. Fase terkait bagian sisi terang yang terlihat; bayangan Bumi berperan pada gerhana Bulan.'],['Bumi lebih dekat ke Matahari adalah penjelasan utama semua musim. Benarkah?','Tidak. Kemiringan sumbu dan revolusi berperan penting, dengan mekanisme iklim regional yang perlu diperhatikan.']],
'Apa yang perlu Anda katakan sebelum menggunakan poster tata surya yang tidak berskala?',('NASA. Solar System Exploration.','https://science.nasa.gov/solar-system/'))

